-- Personal SIWC credentials never enter installation providers.
CREATE TABLE subscription_runtime(singleton INTEGER PRIMARY KEY CHECK(singleton=1), runtime_id TEXT NOT NULL, host_id TEXT NOT NULL) STRICT;
CREATE TABLE chatgpt_bindings(tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,id TEXT NOT NULL,current_revision INTEGER NOT NULL,status TEXT NOT NULL,remote_revoke TEXT NOT NULL DEFAULT 'not_requested',PRIMARY KEY(tenant_id,account_id,id),FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id)) STRICT;
CREATE TABLE chatgpt_binding_revisions(tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,binding_id TEXT NOT NULL,revision INTEGER NOT NULL,label TEXT NOT NULL,client_id TEXT,identity BLOB,PRIMARY KEY(tenant_id,account_id,binding_id,revision),FOREIGN KEY(tenant_id,account_id,binding_id) REFERENCES chatgpt_bindings(tenant_id,account_id,id)) STRICT;
CREATE TABLE chatgpt_sessions(tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,binding_id TEXT NOT NULL,revision INTEGER NOT NULL,generation INTEGER NOT NULL,cipher BLOB,expires_at INTEGER NOT NULL,plan_enabled INTEGER NOT NULL,refresh_state TEXT NOT NULL DEFAULT 'idle',refresh_nonce TEXT,refresh_epoch INTEGER,refresh_until INTEGER,cooldown_until INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,account_id,binding_id),FOREIGN KEY(tenant_id,account_id,binding_id,revision) REFERENCES chatgpt_binding_revisions(tenant_id,account_id,binding_id,revision)) STRICT;
CREATE TABLE chatgpt_auth_attempts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,session_digest BLOB NOT NULL,auth_epoch INTEGER NOT NULL,binding_id TEXT NOT NULL,revision INTEGER NOT NULL,expires_at INTEGER NOT NULL,phase TEXT NOT NULL,FOREIGN KEY(tenant_id,account_id,binding_id,revision) REFERENCES chatgpt_binding_revisions(tenant_id,account_id,binding_id,revision)) STRICT;
CREATE TABLE chatgpt_model_probes(tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,binding_id TEXT NOT NULL,revision INTEGER NOT NULL,model TEXT NOT NULL,effort TEXT NOT NULL,verified_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,account_id,binding_id,revision,model,effort),FOREIGN KEY(tenant_id,account_id,binding_id,revision) REFERENCES chatgpt_binding_revisions(tenant_id,account_id,binding_id,revision)) STRICT;
CREATE TABLE personal_subscription_selections(tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,binding_id TEXT NOT NULL,revision INTEGER NOT NULL,model TEXT NOT NULL,effort TEXT NOT NULL,PRIMARY KEY(tenant_id,account_id),FOREIGN KEY(tenant_id,account_id,binding_id,revision,model,effort) REFERENCES chatgpt_model_probes(tenant_id,account_id,binding_id,revision,model,effort)) STRICT;
CREATE TRIGGER personal_subscription_exclusive AFTER INSERT ON personal_subscription_selections BEGIN DELETE FROM personal_model_selections WHERE tenant_id=NEW.tenant_id AND account_id=NEW.account_id; END;
CREATE TRIGGER personal_shared_exclusive AFTER INSERT ON personal_model_selections BEGIN DELETE FROM personal_subscription_selections WHERE tenant_id=NEW.tenant_id AND account_id=NEW.account_id; END;
CREATE TRIGGER personal_shared_exclusive_update AFTER UPDATE ON personal_model_selections BEGIN DELETE FROM personal_subscription_selections WHERE tenant_id=NEW.tenant_id AND account_id=NEW.account_id; END;
PRAGMA user_version=32;
